const contents = new Map();
const toApply = [];
for (const p of PAYLOADS) {
  if (!contents.has(p.file)) contents.set(p.file, readFileSync(p.file, "utf8"));
  const s = contents.get(p.file);
  if (s.includes(p.apres) && !s.includes(p.avant)) {
    console.log(`  = déjà appliqué: ${p.label}`);
    continue;
  }
  const n = s.split(p.avant).length - 1;
  if (n !== 1) {
    console.error(`ANCRE ${n === 0 ? "INTROUVABLE" : `NON UNIQUE (${n})`} dans ${p.file}`);
    console.error(`  label: ${p.label}`);
    console.error(`  attendu: ${JSON.stringify(p.avant.slice(0, 90))}...`);
    console.error("RIEN n'a été écrit. Dépôt inchangé.");
    process.exit(1);
  }
  toApply.push(p);
}
for (const p of toApply) {
  contents.set(p.file, contents.get(p.file).replace(p.avant, p.apres));
  console.log(`  + ${p.label}  (${p.file})`);
}
for (const [f, s] of contents) writeFileSync(f, s);
console.log(`\npatch 8 appliqué: ${toApply.length} diff(s) écrit(s) sur ${contents.size} fichier(s).`);
if (toApply.length === 0) console.log("Dépôt déjà à jour.");
